/**
 * Comments on a record, with their replies (`design/components/comment-thread.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/comment-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, ownerContext, provide, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/comment-thread.module.css'

export interface CommentThreadMessages {
  edited: string
  replies: string
}

export interface CommentThreadProps {
  /**
   * `CommentThread.Comment`s, in the order they are read.
   */
  children?: JSX.Element
  /**
   * Names the list for a reader: "Comments", not "Thread".
   */
  label: string
  /**
   * The words the member writes itself, for every comment in the thread. English by default.
   */
  messages?: CommentThreadMessages
}

/** What CommentThread hands its compound parts. */
export interface CommentThreadOwner {
  readonly messages: Exclude<CommentThreadProps['messages'], undefined>
}

/** Comments on a record, with their replies. */
export default function CommentThread(given: CommentThreadProps): JSX.Element {
  const props = mergeProps(
    { messages: (() => ({ edited: 'Edited', replies: 'Replies' }))() } as Defaults<
      CommentThreadProps,
      'messages'
    >,
    claimSlot(given),
  )
  return scope(() => {
    provide(ownerContext<CommentThreadOwner>('CommentThread'), {
      get messages() {
        return props.messages
      },
    })
    return (
      <ol class={styles.thread} role="list" aria-label={props.label} data-member="comment-thread">
        {props.children}
      </ol>
    )
  })
}
